#include <Wire.h>
// Электронный игральный кубик: 7 светодиодов, кнопка, пьезо, QMA6100P
// Плата: XIAO ESP32-C3
// Пины:
#define PIN_LED1 2  // D0 - центр
#define PIN_LED2 3  // D1
#define PIN_LED3 4  // D2
#define PIN_LED4 5  // D3
#define PIN_LED5 6  // D6 (TX)
#define PIN_LED6 7  // D7 (RX)
#define PIN_LED7 10 // D10 (MOSI)
#define PIN_BTN 8   // D8/SCK - кнопка на GND (внутр. подтяжка)
#define PIN_BUZZ 9  // D9/MISO - пьезо
#define PIN_SDA 4 // XIAO SDA=D4
#define PIN_SCL 5 // XIAO SCL=D5
// Для XIAO ESP32-C3 фактические GPIO: SDA=6, SCL=7 но Wire использует D4/D5 алиасы
// Используем Wire по умолчанию (D4=SDA, D5=SCL)

const int leds[7] = {PIN_LED1,PIN_LED2,PIN_LED3,PIN_LED4,PIN_LED5,PIN_LED6,PIN_LED7};

// Раскладка точек как на кубике:
// 6 2
// 7 1 3
// 5 4
// LED1=center, LED2=top-left, LED3=top-right, LED4=bottom-right, LED5=bottom-left, LED6=middle-left, LED7=middle-right? Упростим mapping
// Зададим faces битмаской 7 бит (bit0=LED1 center etc)
// Классические грани:
// 1: center
// 2: диагональ 2 точки
// 3: 2+center
// 4: 4 угла
// 5: 4 угла+center
// 6: 6 точек (углы + средние боковые)
// Подгоним под нашу разводку: LED1 центр, LED2/3/4/5 углы, LED6/7 средние
const uint8_t faces[7] = {
  0,
  0b0000001, // 1 - центр
  0b0001010, // 2 - два противоположных угла (LED2+LED4)
  0b0001011, // 3 - 2 + центр
  0b0011110, // 4 - 4 угла LED2+LED3+LED4+LED5
  0b0011111, // 5 - 4 угла + центр
  0b0111111  // 6 - все кроме центра? + добавим средние -> 6 точек
};
// Для 6 используем углы+середины: LED2,LED3,LED4,LED5,LED6,LED7 = 0b1111110 = 0x7E
const uint8_t face6 = 0b1111110;

QMA6100P via I2C: addr 0x12 (AD0=GND) или 0x13
#define QMA_ADDR 0x12
bool hasAccel=false;

void ledsOff(){ for(int i=0;i<7;i++) digitalWrite(leds[i], LOW); }
void showFace(int n){
  uint8_t m = (n==6) ? face6 : faces[n];
  for(int i=0;i<7;i++) digitalWrite(leds[i], (m>>i)&1 ? HIGH : LOW);
}
void buzz(int freq, int ms){
  tone(PIN_BUZZ, freq, ms);
}
void rollAnimation(){
  for(int i=0;i<12;i++){
    int f = random(1,7);
    showFace(f);
    buzz(800 + f*200, 40);
    delay(60);
  }
}
void doRoll(){
  rollAnimation();
  int result = random(1,7);
  showFace(result);
  // победный звук
  buzz(1200,120);
  delay(150);
  buzz(1600,200);
  Serial.printf("Выпало: %d\n", result);
}

// QMA6100P helpers
bool qmaRead(int16_t &x,int16_t &y,int16_t &z){
  Wire.beginTransmission(QMA_ADDR);
  Wire.write(0x00); // chip_id reg?
  // Просто читаем регистры данных 0x01..0x06
  Wire.endTransmission(false);
  Wire.requestFrom(QMA_ADDR, 6);
  if(Wire.available()<6) return false;
  uint8_t d[6]; for(int i=0;i<6;i++) d[i]=Wire.read();
  x = (int16_t)((d[1]<<8)|d[0]) >> 2;
  y = (int16_t)((d[3]<<8)|d[2]) >> 2;
  z = (int16_t)((d[5]<<8)|d[4]) >> 2;
  return true;
}
void initQMA(){
  Wire.begin();
  delay(100);
  // Проверяем ID
  Wire.beginTransmission(QMA_ADDR);
  Wire.write(0x00);
  Wire.endTransmission(false);
  Wire.requestFrom(QMA_ADDR,1);
  if(Wire.available()){
    uint8_t id = Wire.read();
    Serial.printf("QMA ID=0x%02X\n", id);
    hasAccel = true;
    // Включаем активный режим: регистр 0x11 = 0x80? По даташиту PowerMode
    Wire.beginTransmission(QMA_ADDR);
    Wire.write(0x11); Wire.write(0x80);
    Wire.endTransmission();
    // bandwidth
    Wire.beginTransmission(QMA_ADDR);
    Wire.write(0x10); Wire.write(0x0A);
    Wire.endTransmission();
  } else {
    Serial.println("QMA не найден - бросок только кнопкой");
  }
}

unsigned long lastShake=0;
void setup(){
  Serial.begin(115200);
  for(int i=0;i<7;i++){ pinMode(leds[i], OUTPUT); digitalWrite(leds[i], LOW); }
  pinMode(PIN_BTN, INPUT_PULLUP);
  pinMode(PIN_BUZZ, OUTPUT);
  randomSeed(analogRead(0) + micros());
  initQMA();
  showFace(1);
  buzz(1000,100);
  Serial.println("Электронный кубик готов: нажмите кнопку или встряхните!");
}

void loop(){
  // Кнопка (с антидребезгом)
  static unsigned long lastPress=0;
  if(digitalRead(PIN_BTN)==LOW && millis()-lastPress>500){
    lastPress=millis();
    Serial.println("Бросок кнопкой");
    doRoll();
  }
  // Встряхивание по акселерометру
  if(hasAccel && millis()-lastShake>800){
    int16_t x,y,z;
    if(qmaRead(x,y,z)){
      long mag = abs((long)x)+abs((long)y)+abs((long)z);
      // порог встряхивания ~ 2000 LSB, подбирается
      if(mag > 3000){
        lastShake=millis();
        Serial.printf("Shake mag=%ld x=%d y=%d z=%d\n", mag,x,y,z);
        doRoll();
      }
    }
  }
  delay(20);
}
